export const PAGE_TEXT={
 'factor-genome':'Один файл — одно значение фактора. Все основатели варианта получают выбранный геном. Отдельные коэффициенты заменяют только выбранные гены.',
 'factor-founder-senses':'Коэффициент −8…8, не проценты. Без этого параметра сохраняются исходные значения. Меняется геном основателей; потомки наследуют и мутируют по общим условиям.',
 'constructor-genetics':'Все сочетания выбранных значений; максимум 64 на seed. В группе «Геном основателей» доступны файлы геномов и отдельные коэффициенты чувствительности. По умолчанию геномы случайные; загруженная общая основа сохраняет свои значения. Не добавляйте чувствительность, которую хотите оставить исходной.',
 'pair-method':'A — база, B — сравниваемый вариант. Разность B−A; отношение B/A; изменение 100×(B/A−1)%. Для долей разность — в процентных пунктах. Среднее и медиана сохраняют выбранные веса; разность медиан не является медианой разностей. Используются только полные пары исходных повторов для данного показателя, остальные миры остаются в общей статистике. Разные seed выбранных попыток не разрывают исходную пару; видны попытки и вымирания. ДИ приближённые: 999 совместных перевыборок целых пар, от пяти пар; при малом числе повторов особенно осторожная интерпретация. Нулевая или неопределённая относительно нуля база не даёт надёжного интервала отношения. Положительная разность сама по себе не означает улучшения, особенно у знаковых чувствительностей. Набор чисел исследовательский, без автоматического объявления победителя.',
 'history-bands':'ДИ — приближённая неопределённость среднего/медианы по независимым мирам, не диапазон значений особей. При пяти повторах оценка особенно неточна; при меньшем числе ДИ не показан. Полоса поточечная, не одновременная для всей кривой. Разброс 25–75% описывает мировые значения, а не точность оценки. У кривой дожития прежний пунктир означает неизвестные исходы, не ДИ.',
 'experiment-export-kind':'«Результаты опытов»: компактный сжатый архив .beexp без удаления полей; обычный JSON доступен в выборе формата. Архив загружает истории выбранными частями. «Проверки и замеры» — отдельный технический отчёт; «План» — только настройки. Эти файлы не заменяют сохранение полного мира.',
 'experiment-retry-comparison':'Итоги учитывают повторные попытки после вымирания. Они показывают результат настроек вместе с правилом повторов. При разных итоговых seed влияние начального состава жителей отделить сложнее; все попытки и вымирания доступны в строках миров.',
 brand:`BIG EVOLUTION · ${APP_VERSION}`,
 'wiki-start':'Открой «Мир» и нажми «Наблюдать», чтобы запустить время. «Подшаг» продвигает мир на 0,1 Т и оставляет его на паузе. Темп меняет скорость наблюдения, а не законы модели. Общая кнопка «Наблюдать / Пауза» доступна во всех разделах. История обновляется раз в секунду без автоматической паузы; запуск испытаний отдельно приостанавливает основной мир. Нажми на жителя на карте, чтобы увидеть его состояние и решения. Изменение стартовых условий действует после «Начать новый опыт»; перед заменой мира сохрани его кнопкой в верхней строке.',
 'wiki-environment':'Автоматическое изменение источников пищи меняет число островков, их размеры/разброс, вместимости и периоды. Все островки пытаются сместиться целиком на 5–20 гексов; около 20% одиночных кустов перемещаются отдельно до 5 гексов. На островок проверяется до 32 случайных смещений, без перебора всей области. Форма переноса сохраняется, вода и занятые источниками клетки исключаются; при отсутствии допустимого места группа остаётся. Число групп меняется созданием/удалением, без слияния/разделения. Размер меняется по краям. Если компактный рост ограничен сушей, остаток бюджета становится одиночными кустами. Сначала проходят пять событий приближения к целевым числу источников и среднему периоду без шума этих двух средних. Затем среда случайно меняется около целей с возвратом на четверть отклонения. Выбранные границы выработки соблюдаются после подготовки; нижняя граница настраивается. Сначала корректируется число источников, при его пределе — периоды. Нижний порог относится к потенциальному производству пищи, а не к гарантированной численности. Ручное вмешательство отменяет оставшуюся подготовку. Уже лежащая пища сохраняется. Сведения о календаре и глобальных условиях доступны наблюдателю, но не мозгу организма.',
 'wiki-saves':'«Сохранить мир» в верхней строке скачивает полный JSON: жителей, их память и обучение, текущие действия, пищу, календарь среды, историю и состояние случайности. «Загрузить мир» проверяет файл и открывает его на паузе. Ошибка или отмена выбора файла сохраняют прежний мир. Геном и отчёт о жизнях — другие форматы; они не заменяют сохранение мира. Автосохранения пока нет.',
 'wiki-checks':'Перед выпуском выполняется полный локальный набор тестов модели, Workers, интерфейса и форматов. В «Испытаниях» можно дополнительно запустить доступные браузерные механизмы на своём устройстве. Часть этих проверок повторяет локальные тесты, их количества нельзя складывать. Старые проверки удалённых правил не являются проверкой нынешней модели. Успешные тесты не гарантируют отсутствия всех ошибок или появления стаи: для поведения нужны длительные наблюдения.',
 'history-food-context':'Количество пищи на карте зависит и от условий, и от потребления жителями. График помогает сопоставить контекст, но сам по себе не доказывает эволюционное улучшение.',
 'history-method':'Показатели жизней сгруппированы по времени рождения; частоты — события на 100 Т жизни, запас — средний по времени инвентарь. Население и пища сгруппированы по времени мира: сначала среднее за интервал каждого мира, затем сводка этих средних с равным весом миров. Медиана жизней сохраняет выбранные веса особей или миров. Общий период управляет и графиками, и числами; показатели выбранной особи относятся ко всей её жизни. Масштаб учитывает включённые линии и полосы. Пунктир — предварительные данные. Стрелки выбирают интервал, Escape снимает выбор.',
 'history-curve-method':'Возраст → доля доживших. Своя группа рождения, независимо от общего периода; ширина задаётся выше. Сплошная линия — точная доля закрытой группы. Пунктир и полоса — границы возможной доли, если молодые живые ещё не достигли возраста; это не прогноз. Пока интервал рождения открыт, состав группы предварительный.',
 'history-curve-scale':'Ось возраста от 0 до выбранного максимума. Масштаб сохраняется при смене периода рождения: можно сравнивать кривые без автоматического растягивания. Ограничение оси не исключает долгожителей из статистики группы.',
 "description1": "Наследственные склонности · личная память · обучение",
 "description2": "Карта доступна наблюдателю. Житель видит тело и соседние гексы, помнит наблюдения и учится на последствиях. Скрытые клетки не обновляют его память. Готовых целей и маршрутов нет. Пища размещена островками по всей карте; число источников и период восстановления задаются перед новым опытом. Житель начинает с пустой личной памятью.",
 "description3": "Число вычислителей можно менять у живущего мира. Жители, память и обучение сохраняются. Переключение дожидается завершения текущего расчёта; при ошибке остаётся прежний режим. Запись профиля при успешной смене завершается. Авто выбирает число при применении и новом опыте, без постоянной перестройки пула.",
 "description4": "Измерения основного мира: 30 секунд работы, без времени на паузе. Испытания в Workers сейчас не профилируются.",
 "description5": "Оба режима учитывают шаги и промежутки. Подробный также разбирает этапы каждого десятого шага и сильнее влияет на скорость.",
 "description6": "На старте ёмкости случайные, 3–6 порций; автоматика может их менять. Ручное изменение числа источников/островков или разброса размеров перераспределяет источники. Лежащая еда остаётся на своих клетках, новые источники не получают бесплатного урожая. Применение сохраняет режим запуска мира и отменяет оставшиеся начальные обеднения. Ниже автоматического минимума автоматика выключается.",
 "description7": "Условия ещё не менялись.",
 "description8": "Здесь последние восемь изменений. Все изменения и результаты жизней входят в скачиваемые наблюдения.",
 "description9": "Вероятности для нынешних наблюдений. Геном — врождённая основа, опыт меняется за жизнь. Оценки Q не являются вероятностью выживания.",
 "description10": "12 последних наблюдений из личной памяти.",
 "description11": "Самочувствие −100…+100 — внутренняя оценка с наследуемыми весами. Это не общая шкала приспособленности геномов.",
 "description12": "Источник — одна клетка, островок — группа источников. Около 20% источников — одиночные кусты. Островки делят оставшийся бюджет, их число ограничивается доступными источниками. У каждой группы собственные период и случайная фаза. Каждый неполный источник получает одну порцию в момент плодоношения группы; полные не копят пропущенные порции.",
 "description13": "Наследуемая изменчивость: у случайных основателей вероятность 0,1–10% и сила ±0,05…1, индивидуально. Значения развиваются через поколения.",
 "description14": "Одна общая добавка для основателей, повторяемая по номеру опыта. Без галочки новые гены нулевые: ощущения и реакции памяти нейтральны до мутаций.",
 "description15": "Явное преобразование: мозг сохранится, добавятся два случайных регулятора. Одна общая пара для всех основателей, повторяемая по номеру опыта. Без галочки старая основа не расширяется.",
 "description16": "Настройки вступают в силу при новом запуске. Перезапуск создаёт новую популяцию. Вымирание само её не возрождает.",
 "description17": "Одна компактная запись на жизнь. Средний возраст смерти относится к умершим; возраст живого — незавершённое наблюдение. Кнопка «Настройки статистики» рядом с основными вкладками открывает панель слева и сдвигает данные; Escape закрывает её. Источник и общий период задаются в этой панели. Сохрани мир или скачай результаты перед новым опытом и обновлением страницы.",
 "description18": "Выбери строку жизни.",
 "description19": "«Предел возраста» пока означает достижение 10 000 шагов. Износ и восстановление тела — будущая идея. Сводки питания включают все завершённые жизни, а не только видимые строки. Причина гибели определяется текущими правилами; несколько неблагоприятных факторов могут действовать вместе.",
 "description20": "Выберите шаблон или составьте план общих условий и сравниваемых вариантов. Результаты доступны в разделе «Запуски» и на общей странице «Статистика». Проверки механизмов и замеры скорости сохранены в отдельных разделах.",
 "description21": "Обычная остановка возвращает текущие итоги миров. Немедленное прерывание сохраняет уже полученные результаты и последний прогресс. Каждая подвкладка хранит свой последний отчёт в этом браузере. Новый запуск заменяет только результаты своего раздела. После обновления работающие миры не продолжаются. Общий JSON сохраняет имеющиеся результаты всех трёх разделов и версии их сборок.",
 "description22": "Дополнительные изолированные проверки текущей модели: длительности, прерывания, наследование, память, обучение и балансы. Перед выпуском выполняется также полный локальный набор тестов Workers, интерфейса и форматов. Часть проверок повторяется; их числа нельзя складывать. Успешный набор не гарантирует отсутствия всех ошибок. Фикстуры используют управляемые условия; обычные основатели остаются случайными.",
 "description23": "Выбери версии и под каждой — сравниваемые числа вычислителей. Каждый полный мир начинается с одинакового состояния в рамках версии. Режимы выполняются по очереди с ротацией и отдельным прогревом. Одновременно активен один пул; основной мир на паузе. Оценщики последовательные и измеряются один раз на версию.",
 "description24": "Перед запуском закрой тяжёлые приложения. Оставь вкладку браузера на переднем плане. Обычный мир остаётся на паузе.",
 "description25": "<a href=\"./source.html?file=docs/action-time-spec.md\">Действующая модель</a>: сначала проверки механизмов, затем выбранная география и одинаковые пищевые условия на нескольких seed. Для основного наблюдения достаточно памяти и TD.",
 "description26": "Один выбранный набор пищи применяется ко всем мирам этого пакета. Для сравнения с другим набором сначала скачай отчёт, затем запусти новый пакет. Настройки обычного мира независимы.",
 "description27": "Случайные геномы с нуля.",
 "description28": "По умолчанию 12 seed × 3 режима = 36 миров. Каждый пакет использует выбранные число источников и период восстановления. Один seed сохраняет одинаковый старт режимов, дальнейшие случайные события могут расходиться.",
 "description29": "Длительность мира, дожившего до конца, ограничена сроком наблюдения. Его полный срок жизни ещё неизвестен. Субъективные чувства разных геномов не служат общей шкалой приспособленности.",
 "description30": "В полном отчёте — пищевые сводки всех смертей (порции, промежутки, доля действий), правила, контрольные точки, длительность существования популяции, причины смерти, возрастные сводки, незавершённые жизни, проверки баланса и геномы. Для каждого мира сохранены последние 250 подробных итогов смерти; накопительная статистика учитывает все жизни. В обычной вкладке историй такого сокращения нет.",
 "description31": "Образцы по числу потомков, возрасту и поколению. Это разные критерии, ни один не обозначает «самый лучший организм».",
 "description32": "Загрузи один или два экспорта генома v13, v11 либо прежних v1–v9. v10 несовместим и не преобразуется. Анализ выполняется в браузере, файлы не отправляются на сервер и не загружаются как основа мира. Истории жизней и испытания пока не поддерживаются. Переключение разделов не останавливает мир; для остановки используй общую кнопку «Пауза».",
 "description33": "Файл не загружен.",
 "description34": "Файл не загружен.",
 "description35": "Сырое число — ген; пересчитанное — скорость, вместимость или длительность. Доли шкалы чувств имеют знак и нормированы суммой модулей весов ощущений. Это не доли текущего удовольствия и не оценка качества генома. Нулевой ген нейтрален; отсутствующий ген помечен отдельно.",
 "description36": "Это сохранённый контекст, а не текущее состояние особи или проверка достоверности её истории.",
 "description37": "Это браузерная лаборатория: организмы действуют, расходуют конечные ресурсы, рождают потомство и погибают. Мы наблюдаем, какие наследственные склонности сохраняются и что меняется за одну жизнь. Оптимальное поведение, миграция или появление общества не обещаны.",
 "description38": `${TEMPORAL_LAYOUT.genes+2} наследуемых чисел: ${SET_PARAMETER_COUNT} параметров основного мозга, 12 свойств ощущений, памяти и обучения, ${GATE_PARAMETERS} параметров малого мозга и два регулятора мутаций. На своей и соседних клетках видны количества других особей по всем текущим действиям и шести направлениям движения относительно наблюдателя. Это не готовая стратегия следования или сотрудничества.`,
 "description39": "Основатели обычно получают случайные числа. Потомок копирует геном одного родителя; при включённых мутациях часть чисел меняется. Геном организма за жизнь не переписывается.",
 "description40": "Организмы с разным поведением оставляют разное количество потомков. Поэтому распространённость геномов меняется. Никто не получает назначенные очки за «правильное» поведение, а вымершая популяция не заселяется заново автоматически.",
 "description41": "Это модель эволюции с условностями. Рождение ещё не означает успешного взрослого потомка, а оставшаяся линия не обязательно имеет единственный геном: мутации продолжаются.",
 "description42": "Шагнуть к одному из шести соседей, подобрать порцию, съесть её, ждать, родить или положить одну порцию на землю. Направления отсчитываются от собственного взгляда. Житель наблюдает тело и соседние клетки; вся карта доступна только тебе.",
 "description43": "Готовых стратегий поиска еды, накопления запасов и миграции нет. При этом физика, восприятие, допустимые действия и алгоритм выбора заданы разработчиком — модель не начинается без любых предпосылок.",
 "description44": `Да. Небольшая сеть «клетки → общая ситуация → все Q» оценивает каждый доступный вариант. Скрытые нейроны используют tanh, выход — прогноз последствий Q. Из оценок получаются вероятности; житель выбирает допустимое действие. Новая модель использует геном v13; наследуемая малая сеть внимания ${GATE_INPUTS} → 4 → 1 может запросить пересмотр, в том числе при изменении видимой деятельности других.`,
 "description45": "Личное обучение (Expected SARSA с градиентным следом) сравнивает ожидаемые субъективные последствия с полученным ощущением и ожидаемым продолжением. Меняются личные поправки к связям и смещениям, геном остаётся прежним. Обучение может улучшать или ухудшать поведение в этих условиях. Его наличие само по себе не доказывает преимуществ.",
 "description46": "Краткая память хранит недавние наблюдения. Повторные возвращения, сильные или неожиданные ощущения могут закрепить место в долгой памяти. Объём ограничен генами, записи могут забываться и пересматриваться.",
 "description47": "Житель начинает с личной позиции (0, 0) и пустого опыта. Места, освоенные родителем, ребёнку не передаются. Память может работать при выключенном личном обучении. Пока собственные перемещения считаются точно и дополнительной энергетической цены памяти нет.",
 "description48": "Источники — клетки, объединённые в островки, и одиночные кусты между ними. Общее число источников и число островков задаются отдельно; средний размер связан с этим бюджетом. Размеры получают равномерные случайные веса с заданным разбросом и округляются до целых с сохранением общего числа. Это не нормальное распределение и не σ.",
 "description49": "Средний период и относительный разброс задают периоды групп. Каждый островок и одиночный куст имеют собственную случайную фазу. При наступлении срока неполный источник получает одну порцию, полный пропускает пополнение без накопления долга. Дробные периоды используют физическую сетку 0,1 Т. В режиме автоматики поля текущего мира показывают текущие параметры и заблокированы; для ручного изменения выключи автоматику.",
 "description50": "Пищевые таймеры жителям не раскрываются. Можно сочетать мало источников с быстрым восстановлением или много с медленным. Ожидание, переходы и вымирание — возможные результаты. При одинаковом seed пищевые настройки не сдвигают начальные геномы и позиции жителей.",
 "description51": "По умолчанию карта получает случайные связные реки и компактные озёра. Вода непроходима, броды — сухие разрывы для перехода. Итоговая площадь воды не превышает 20%; отдельные районы могут оставаться изолированными.",
 "description52": "Основатели пространственно распределены по всей суше, по одному месту в разнесённых участках. Их места не подбираются к пище. Источники остаются островками на суше; число, ёмкости, стартовые запасы и период задаются прежними правилами. Один seed сохраняет начальные геномы при смене профиля географии.",
 "description53": "В обычных настройках доступна только карта с реками и озёрами. Прежние профили сохранены для технических проверок. Профиль и сведения о районах записываются в JSON. Обзор сейчас радиусом 1 во всех профилях; лес и радиус 2 ещё не добавлены.",
 "description54": "В панели «Изменить текущий мир» можно применить число источников, период, общую ёмкость 1–24 или новую раскладку. Применение выполняется между целыми шагами и сохраняет режим запуска: работающий мир продолжает, приостановленный остаётся на паузе. Шаг, жители, геномы, память и родословные продолжают ту же историю.",
 "description55": "Вместимость настраивается средним значением и равномерным разбросом целых ёмкостей в физических пределах; по умолчанию 3–6 порций. Изменение числа источников или размеров островков может перераспределить их. Периоды можно менять без переноса. Лежащая пища остаётся на своих клетках, а новые источники не получают бесплатного урожая. Снижение вместимости не удаляет избыток пищи. Ручное применение создаёт новое расписание и отменяет оставшиеся подготовительные обеднения.",
 "description56": "Жители не получают извещения о перестановке: они заново наблюдают местность и могут пересмотреть прежние воспоминания. В журнале сохраняются шаги и итоги изменений, на графике они отмечены пунктиром. «Скачать наблюдения» выгружает журнал и результаты жизней для анализа; для изменения среды сохранение генома не требуется.",
 "description57": "Житель может выбрать «Положить»: одна порция переносится из инвентаря на текущую сушу за 3 подшага и 0,108 энергии (плюс цена решения). Действие доступно, если на клетке меньше 10 порций. Любой житель может подобрать оставленное; владельца и отдельной награды за запасание нет.",
 "description58": "Вне источника пища сохраняется до сбора и сама не растёт. Перенос с полного источника освобождает место для следующего пополнения. Естественная ёмкость источников не меняется; еда выше 10, выросшая или сохранившаяся при редактировании, не обрезается. Будущий склад-здание и уничтожение еды ещё не реализованы.",
 "description59": "Смотри на длительность жизни, причины гибели, потомство и устойчивость популяции вместе. Самочувствие −100…+100 зависит от наследуемых знаков чувствительности; это не универсальная шкала качества жизни разных геномов.",
 "description60": "Концентрация возле еды может возникнуть из-за личной памяти, врождённых склонностей или гибели ушедших. Для различения причин нужны одинаковые старты в режимах «без памяти и TD», «память без TD» и «память и TD», несколько seed и долгие наблюдения.",
 "description61": "Один родитель, добровольное рождение при допустимом состоянии тела, самостоятельный ребёнок сразу после рождения, предел возраста 10 000 шагов. Заживления, зависимого детства, драк, хищников, строительства и культуры пока нет. Лимит живых — вычислительное ограничение, влияющее на рождения.",
 "description62": "Шаг не равен году. Автоматического сохранения нет: перед обновлением страницы сохрани мир кнопкой в верхней строке. Полное сохранение можно загрузить и продолжить на паузе; геном и аналитический отчёт такого состояния не содержат. Опыты выполняются в твоём браузере; завершённые попытки сохраняются локально. Результаты можно скачать архивом .beexp или JSON, планы — в JSON.",
 "description63": "Значок ? возле настройки или действия открывает пояснение. Нажми его на телефоне или выбери клавишей Tab и нажми Enter. Закрытие — кнопкой или Escape. <a href=\"./source.html\">Исходники с русскими комментариями</a> · <a href=\"./source.html?file=docs/future-ideas.md\">Будущие идеи</a>",
 "description64": "JavaScript · физика отделена от интерфейса · показатели не доказывают закономерности реальной эволюции",
 "description65": "Мир состоит из гексов. Житель видит свою клетку и шесть соседних, пищу и наличие источников даже без еды. Он не знает скрытого расписания восстановления. Вода непроходима, броды проходимы. Опасных клеток и боли нет.",
 "description66": `Одна единица времени содержит${SUBSTEPS} подшагов. Длительности: движение${ACTION_DURATIONS[0]}, сбор${ACTION_DURATIONS[6]}, еда${ACTION_DURATIONS[7]}, ожидание${ACTION_DURATIONS[8]}, выкладывание${ACTION_DURATIONS[10]}, роды${ACTION_DURATIONS[9]}. Результат появляется при завершении; прерывание сохраняет расходы и время, незавершённый переход оставляет жителя на исходном гексе.`,
 "description67": `Расход энергии за1Т: движение${readable(actionEnergyCost(0))}, сбор${readable(actionEnergyCost(6))}, еда${readable(actionEnergyCost(7))}, ожидание${readable(actionEnergyCost(8))}, выкладывание${readable(actionEnergyCost(10))}. Порция${RULES.foodEnergy}, усвоение${RULES.digestionRate}/Т, инвентарь${RULES.inventoryCapacity} порции, желудок${RULES.stomachCapacity}. Избыток теряется. Неоплаченный расход стоит${readable(ENERGY_DEFICIT_FACTOR)} здоровья за единицу энергии; отдельного плоского штрафа голодания нет.`,
 "description68": "Основной выбор стоит 0,10 энергии. Плановый повтор той же деятельности — 0,03; у движения сравнивается фактическое направление. Пересмотр по малому мозгу и срыв всегда стоят 0,10. Неоплаченная часть расхода, включая мышление, переводится в потерю здоровья по тому же коэффициенту. Малый наследуемый мозг проверяет ситуацию каждый подшаг и может запросить основной выбор. Продолжение сохраняет прогресс, новая попытка начинается с нуля.",
 "description69": "Роды начинаются при возрасте от 90, энергии от 50, здоровье от 40 и интервале от 100 единиц времени. Во время родов другие действия и добровольный пересмотр заблокированы. Живой родитель с 32 энергией в конце передаёт 28 ребёнку и тратит 4 на роды. Лимит населения проверяется при начале; уже начатые роды могут превысить его. Смерть до завершения отменяет рождение. Предельный возраст — 10 000 единиц времени.",
 "description70": `Геном v13: ${SET_PARAMETER_COUNT} параметров основного мозга, 12 свойств ощущений, памяти и обучения, ${GATE_PARAMETERS} параметров малого мозга и 2 регулятора мутаций — ${TEMPORAL_LAYOUT.genes+2} чисел. Начальные связи случайны, готовые стратегии не заложены. Геномы v12 не импортируются и не преобразуются. Личный опыт и воспоминания не наследуются. Основной мозг обучается при следующем выборе у живой особи; обучение при смерти не выполняется.`,
 "description71": "Краткая память получает видимые факты каждый подшаг. Время наблюдения учитывается долями, поэтому частота наблюдений сама по себе не усиливает закрепление. Источник не сохраняется в долгую память автоматически. Социальной памяти, атак, силы и скорости тела пока нет."
};

Object.assign(HELP,{
 step:['Один подшаг','Ставит наблюдение на паузу и выполняет один подшаг (0,1 Т). Десять последовательных подшагов дают тот же результат, что один полный шаг.'],
 speed:['Темп наблюдения','Медленное наблюдение: 2, 4 или 10 подшагов/с (1 Т/с). На видимой карте показывается каждый подшаг; если отрисовка отстаёт, показ замедляется. В фоне и других разделах расчёт не ждёт кадра. Ускоренные режимы: 8× — 80 Т/с, 32× — 320 Т/с, 64× — 640 Т/с. Если устройство не успевает, фактическая скорость ниже. Темп не меняет стоимость и длительность действий в модельном времени.'],
 'food-period':['Средний период восстановления','Среднее значение для равномерного разброса периодов групп. Обычный диапазон ползунка — до 300 Т; текущие автоматические условия могут расширить отображаемый диапазон. Дробные значения используют сетку 0,1 Т. Это параметр среды, недоступный мозгу.'],
 'food-size-mean':['Средний размер островка','Связан с общим числом источников и числом островков. Изменение среднего размера пересчитывает бюджет источников в пределах карты. Из-за целых размеров возможна ближайшая достижимая величина. Одиночные кусты считаются отдельно.'],
 'food-capacity-mean':['Средняя вместимость диапазона','Середина минимальной и максимальной вместимости источников. Вместе с разбросом задаёт равномерное распределение целой вместимости от 1 до 24 порций. Среднее конкретной небольшой выборки может отличаться.'],
 'food-capacity-spread':['Разброс вместимости','Процент отклонения границ от среднего. Например, среднее 4,5 и разброс 33,33% задают вместимости от 3 до 6 порций. Границы округляются до целых и ограничиваются 1…24. Это диапазон, не стандартное отклонение σ.'],
 'history-display':['Экран статистики','Показывает выживание, поведение, ресурсы, таблицу или конструктор анализа. В конструкторе свои формулы, группы, период и веса одного опыта; остальные экраны используют общую боковую панель. Можно выбрать собственный набор прежних графиков; их фильтры и данные при переключении сохраняются.'],
 'food-islands':['Количество островков','Общее число групп. Ноль оставляет только одиночные кусты. Средний размер связан с числом источников; целые размеры и доступная суша ограничивают достижимые значения.'],
});
for(const name of ['period','size-mean','capacity-mean','capacity-spread'])ALIASES['world-food-'+name]='food-'+name;
for(const prefix of ['', 'world-'])for(const name of ['sources','period','period-spread','size-spread','size-mean','capacity-mean','capacity-spread'])ALIASES[prefix+'food-'+name+'-number']=ALIASES[prefix+'food-'+name]??prefix+'food-'+name;
// Каталог нормализуется один раз, вне кадрового цикла. Динамические значения
// добавляются с явными разделителями в своих модулях представления.
for(const entry of Object.values(HELP)){entry[0]=typography(entry[0]);entry[1]=typography(entry[1]);}
for(const key of Object.keys(PAGE_TEXT))PAGE_TEXT[key]=typography(PAGE_TEXT[key]);
export const UI_TEXT={
 activities:cell=>'Деятельность других: '+(ACTIONS.map((name,i)=>{const n=cell.activities?.[i]??0;return n?`${i<6?'движение ':''}${name.toLowerCase()} — ${n}`:'';}).filter(Boolean).join('; ')||'нет выполняемых действий')+'.',
 evaluatorOnce:'Последовательный оценщик: один замер на версию; число вычислителей не применяется.',
 scalingMetrics:'Ускорение и эффективность рассчитаны относительно минимального выбранного числа вычислителей своей версии. Для базы1 эффективность = ускорение / число вычислителей. Это не загрузка CPU. Неполные или разные итоги не получают ускорения. Автоматического выбора режима нет.',
 benchmarkFinished:'Замеры завершены. Ускорение показано в разах и процентах скорости; эффективность — доля пропорционального масштабирования. Скачай JSON.',
 computations:computationLabel,
 currentComputations:(n,mode)=>`Сейчас: ${computationLabel(n)}${mode==='auto'?' · режим Авто':''}`,
 computeChanged:(n,tick)=>`Сейчас: ${computationLabel(n)}. Применено после шага ${tick}; мир продолжает ту же историю.`,
};
export function installUIText(root=document){
 for(const element of root.querySelectorAll('[data-ui-text]')){
  const key=element.dataset.uiText;
  if(key==='release')element.textContent=`Версия ${APP_VERSION}`;
  else if(PAGE_TEXT[key]!==undefined)element.innerHTML=PAGE_TEXT[key];
  else throw new Error('Отсутствует текст интерфейса: '+key);
 }
}
